import * as React from 'react';
import { cva, type VariantProps } from 'class-variance-authority';
import { cn } from '@/lib/utils';

const spinnerVariants = cva(
  'inline-block animate-spin rounded-full border-2 border-current border-t-transparent text-muted-foreground motion-reduce:animate-none',
  {
    variants: {
      size: {
        sm: 'h-3 w-3',
        default: 'h-4 w-4',
        lg: 'h-6 w-6',
      },
    },
    defaultVariants: {
      size: 'default',
    },
  }
);

export interface SpinnerProps
  extends React.HTMLAttributes<HTMLSpanElement>,
    VariantProps<typeof spinnerVariants> {
  /** Accessible label announced to screen readers; set aria-hidden when purely decorative. */
  label?: string;
}

function Spinner({ className, size, label = 'Loading...', ...props }: SpinnerProps) {
  return (
    <span
      role="status"
      className={cn(spinnerVariants({ size }), className)}
      {...props}
    >
      <span className="sr-only">{label}</span>
    </span>
  );
}

export { Spinner, spinnerVariants };

{
  "id": "spinner",
  "name": "Spinner",
  "tier": "atom",
  "description": "Indeterminate loading indicator with accessible status semantics.",
  "designIntent": "Communicate in-progress states without layout shift; inherit text color so it adapts to any context.",
  "props": [
    {
      "name": "size",
      "type": "'sm' | 'default' | 'lg'",
      "defaultValue": "default",
      "required": false,
      "description": "Visual size of the spinner."
    },
    {
      "name": "label",
      "type": "string",
      "defaultValue": "Loading...",
      "required": false,
      "description": "Screen-reader label; the visual ring is aria-hidden."
    }
  ],
  "examples": [
    {
      "title": "Default",
      "code": "<Spinner />"
    },
    {
      "title": "Inline loading state",
      "code": "<span className=\"flex items-center gap-2\"><Spinner size=\"sm\" /> Generating...</span>"
    },
    {
      "title": "Decorative (near visible text)",
      "code": "<Spinner aria-hidden label=\"\" />"
    }
  ],
  "antiPatterns": [
    {
      "title": "Do not use multiple spinners for one wait state",
      "explanation": "One status indicator per operation; multiple role=status elements announce redundantly."
    }
  ],
  "accessibility": [
    {
      "feature": "Status semantics",
      "implementation": "role=status with sr-only label announces loading to screen readers."
    },
    {
      "feature": "Reduced motion",
      "implementation": "Pair with motion-reduce utilities when animation must be suppressed."
    }
  ],
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.0.1",
  "sourceDir": "spinner",
  "exportName": "Spinner"
}
